INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('3d5a80493ad1b6638fa4','AMEDEX 2025 NEUROLOGY (2).pdf','5','Neurology','A 55-year-old man presents to your GP clinic
with complaints of tinnitus and hearing loss in
his right ear. According to him, he suddenly felt
a severe spinning sensation associated with
ringing in and hearing loss of his right ear while
working. He felt intensely nauseous but did not
vomit. He could not stand so he lied down in
bed. After five hours, the spinning partially
improved and only has been coming on with
head movements, but he still has the ringing ear
and deafness. Except for the sensorineural
deafness of the right ear and nystagmus on
ocular movements, physical examination,
including a full neurological exam, Is
unremarkable. Which one of the following could
be the most likely diagnosis?','{"A":"Labyrinthitis.","B":"Vestibular neuronitis.","C":"Acoustic neuroma.","D":"Benign paroxysmal positional vertigo.","E":"Meniere''s disease."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-00a924e4fb42","duplicate_sources":[{"record_id":"3d5a80493ad1b6638fa4","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_page":5,"source_qid":null},{"record_id":"35cac525b4f956a45269","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":785,"source_qid":"1377"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"3d5a80493ad1b6638fa4","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_year":2025,"source_page":5,"source_qid":null,"domain_hint":"Neurology","stem":"A 55-year-old man presents to your GP clinic\nwith complaints of tinnitus and hearing loss in\nhis right ear. According to him, he suddenly felt\na severe spinning sensation associated with\nringing in and hearing loss of his right ear while\nworking. He felt intensely nauseous but did not\nvomit. He could not stand so he lied down in\nbed. After five hours, the spinning partially\nimproved and only has been coming on with\nhead movements, but he still has the ringing ear\nand deafness. Except for the sensorineural\ndeafness of the right ear and nystagmus on\nocular movements, physical examination,\nincluding a full neurological exam, Is\nunremarkable. Which one of the following could\nbe the most likely diagnosi