INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('49b280a761b09fae9132','AMEDEX 2025 NEUROLOGY (2).pdf','40','Neurology','A 56-year-old man presents to the emergency
department with complaint of diplopia. On
examination, he has right-sided ptosis. His
visual acuity and visual fields are unaffected.
His right eye is depressed inferiorly and laterally
and he is not able to look at to the left side. The
pupillary light reflex of the right eye is sluggish.
The neurological examination is otherwise
unremarkable. Which one of the following can
be the most likely cause to this presentation?','{"A":"Midbrain infarct.","B":"Right 6\"” nerve palsy.","C":"Posterior communicating artery\naneurysm.","D":"Right 4in nerve palsy.","E":"lesion in the occipital cortex."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-9cccefd300a6","duplicate_sources":[{"record_id":"49b280a761b09fae9132","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_page":40,"source_qid":null},{"record_id":"ed032f7866639345f369","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_page":41,"source_qid":null},{"record_id":"5fde79703329e793953f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":750,"source_qid":"1245"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"49b280a761b09fae9132","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_year":2025,"source_page":40,"source_qid":null,"domain_hint":"Neurology","stem":"A 56-year-old man presents to the emergency\ndepartment with complaint of diplopia. On\nexamination, he has right-sided ptosis. His\nvisual acuity and visual fields are unaffected.\nHis right eye is depressed inferiorly and laterally\nand he is not able to look at to the left side. The\npupillary light reflex of the right eye is sluggish.\nThe neurological examination is otherwise\nunremarkable. Which one of the following can\nbe the most likely cause to thi