INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ec6fbd9bbe5446fc9bab','AMEDEX 2025 NEUROLOGY (2).pdf','58','Neurology','You are assessing Tim, a 65-year-old man, who
is brough to the Emergency Department after
his wife suspected there may be something
wrong with him. She noticed that he had been
shaving only the right side of his face for the
past 2 days. Assessment suggests ischemic
stroke and you are performing a neurological
examination on him. In the physical
examination, when you ask him to lift his left
arm, he raises his right arm instead. Which one
