INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d9b64c224ea996a4e41f','AMEDEX 2025 NEUROLOGY (2).pdf','99','Neurology','A 22-year-old man presents to your GP clinic
for assessment. On waking up this morning,
he felt pain in his left ear, associated with
severe dizziness and loss of balance. He
describes that the dizziness was felt as
Spinning sensation and giddiness followed by
Nausea and vomiting. The symptoms
Significantly improve when he lies down. He
denies any hearing loss or ringing in the ears.
Physical examination reveals normal vital
Signs. There is horizontal nystagmus with the
rapid component to the right side. Caloric
test shows markedly reduced response on
the left side. The rest of the exam, including a
full assessment of cranial nerves, is
unremarkable. Which one of the following
could be the most likely diagnosis?','{"A":"Meniere''s disease.","B":"Vestibular neuronitis.","C":"Vertebrobasilar ischemia.","D":"Paroxysmal positional vertigo.","E":"Acute labyrinthitis. ©"}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-2289c26b5b76","duplicate_sources":[{"record_id":"d9b64c224ea996a4e41f","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_page":99,"source_qid":null},{"record_id":"ab0fbb69771140ae35ac","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_page":98,"source_qid":null},{"record_id":"b27234e50dcad001e22e","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":782,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"d9b64c224ea996a4e41f","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_year":2025,"source_page":99,"source_qid":null,"domain_hint":"Neurology","stem":"A 22-year-old man presents to your GP clinic\nfor assessment. On waking up this morning,\nhe felt pain in his left ear, associated with\nsevere dizziness and loss of balance. He\ndescribes that the dizziness was felt as\nSpinning sensation and giddiness followed by\nNausea and vomiting. The symptoms\nSignificantly improve when he lies down. He\ndenies any hearing loss or ringing in the ears.\nPhysical examination reveals normal vital\nSigns. There is horizontal nystagmus with the\nrapid component to the right side. Caloric\ntest shows markedly reduced response on\nthe left side. The rest of the exam, including a\nfull assessment of cranial nerves, is\nunremarkable. Which one of the following\ncould be the most likely diagnosis?","options":{"A":"Meniere''s disease.","B":"Vestibular neuronitis.","C":"Vertebrobasilar ischemia.","D":"Paroxysmal positional vertigo.","E":"Acute labyrinthitis. ©"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"2289c26b5b7609bd0e5114d5eef8237c5c248a6f","duplicate_group_id":"exact-2289c26b5b76","duplicate_sources":[{"record_id":"d9b64c224ea996a4e41f","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_page":99,"source_qid":null},{"record_id":"ab0fbb69771140ae35ac","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_page":98,"source_qid":null},{"record_id":"b27234e50dcad001e22e","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":782,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded