years old, and at several occasions in the past
month has had vertigo, right sided hearing loss
and double vision as well as numbness of his
left limbs. These episodes last for up to 5-10
minutes and resolve spontaneously. He smokes
10-15 cigarettes and drinks 2-3 standard drinks
every day. His past medical or surgical history is
insignificant and he is not on any regular
medication. He also denies any recent flu-like
symptoms. His family history is remarkable for
Meniere''s disease in his mother. Which one of
the following could be the most likely diagnosis?','{"A":"Multiple sclerosis.","B":"Vertebrobasilar insufficiency.","C":"Meniere''s disease.","D":"Labyrinthitis.","E":"Meningioma."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","supporting_pages":[163],"source_qid":null,"duplicate_group_id":"exact-ce0aad6fbd04","duplicate_sources":[{"record_id":"89af9a97ea35bb403eb1","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_page":163,"source_qid":null},{"record_id":"9c929da585d5a7caf753","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":790,"source_qid":"1383"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"89af9a97ea35bb403eb1","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_year":2025,"source_page":163,"supporting_pages":[163],"source_qid":null,"domain_hint":"Neurology","stem":"Ben is in your clinic for assessment. He is 60\nyears old, and at several occasions in the past\nmonth has had vertigo, right sided hearing loss\nand double vision as well as numbness of his\nleft limbs. These episodes last for up to 5-10\nminutes and resolve spontaneously. He smokes\n10-15 cigarettes and drinks 2-3 standard drinks\nevery day. His past medical or surgical history is\ninsignificant and he is not on any regular\nmedication. He also denies any recent flu-like\nsymptoms. His family history is remarkable for\nMeniere''s disease in his mother. Which one of\nthe following could be the most likely diagnosis?","options":{"A":"Multiple sclerosis.","B":"Vertebrobasilar insufficiency.","C":"Meniere''s disease.","D":"Labyrinthitis.","E":"Meningioma."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"ce0aad6fbd042d15da446b0060dbd045eade0aec","duplicate_group_id":"exact-ce0aad6fbd04","duplicate_sources":[{"record_id":"89af9a97ea35bb403eb1","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_page":163,"source_qid":null},{"record_id":"9c929da585d5a7caf753","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":790,"source_qid":"1383"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
