ce":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":true,"parser_confidence":"very_high","parser_mode":"human_visual_review_batch010","text_method":"manual_visual_plus_context","parser_version":"manual-review-batch010-2026-09-24","visual_asset":"manual_review_assets/AMEDEX_2025_NEUROLOGY_2__d3816bb7b8b9/page_00171.jpg","visual_source_page":169,"manual_review_batch":"010","manual_review_source_key":"","stem_hash":"c9f2b5da81367b89019dcc7f7676131939033795d45f174362e720fd86dad767","visual_assets":["manual_review_assets/AMEDEX_2025_NEUROLOGY_2__d3816bb7b8b9/page_00171.jpg"]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
