INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('76825d4141e5e98fa3d2','AMEDEX 2025 NEUROLOGY (2).pdf','175','Neurology','A 58-year-old man presents with complaint of
progressive difficulty in walking for the past few
months. He denies any pain or pins and
needles. On examinations, he drags his left foot
on walking. On the left side, ankle tendon
reflexes are exaggerated and the strength of
plantar flexion and dorsiflexion are decreased to
4/5. Sensation is intact. The right foot is
completely normal. Plantar reflexes are
equivocal bilaterally. The rest of the physical
examination including neurologic exam of the
face and upper extremities are unremarkable.
Lesions of which one of the following parts
could be the mostly likely cause to this
presentation?','{"A":"Common peroneal nerve.","B":"L5/S1 nerve root.","C":"Cervical spine.","D":"Brainstem.","E":"Cerebral cortex."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-a3df7f3ba8cc","duplicate_sources":[{"record_id":"76825d4141e5e98fa3d2","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_page":175,"source_qid":null},{"record_id":"47bbf3d3e2397c351b40","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":749,"source_qid":"1239"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"76825d4141e5e98fa3d2","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_year":2025,"source_page":175,"source_qid":null,"domain_hint":"Neurology","stem":"A 58-year-old man presents with complaint of\nprogressive difficulty in walking for the past few\nmonths. He denies any pain or pins and\nneedles. On examinations, he drags his left foot\non walking. On the left side, ankle tendon\nreflexes are exaggerated and the strength of\nplantar flexion and dorsiflexion are decreased to\n4/5. Sensation is intact. The right foot is\ncompletely normal. Plantar reflexes are\nequivocal bilaterally. The rest of the physical\nexamination including neurologic exam of the\nface and upper extremities are unremarkable.\nLesions of which one of the following parts\ncould be the mostly likely cause to this\npresentation?","options":{"A":"Common peroneal nerve.","B":"L5/S1 nerve root.","C":"Cervical spine.","D":"Brainstem.","E