INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('3f139108e62dbcab29ee','AMEDEX 2025 NEUROLOGY (2).pdf','180','Neurology','An eight-year-old boy is brought to your practice
by his mother for what she calls funny turns in
the past several weeks. According to the
mother, the boy have episodes of sudden stares
along with fidgeting of the right hand fingers and
right arm, lip smacking and chewing movements
while his head twitches to the right side. He has
3 to 4 episodes every day with each lasting 60-
90 seconds. There is always spontaneous
resolution after which the child is confused for 1
to 2 minutes before he becomes completely
himself and back to whatever he was doing
before. Which one of the following is the most
likely diagnosis?','{"A":"Temporal lobe epilepsy.","B":"Juvenile myoclonic epilepsy.","C":"Absence seizure.","D":"Hypsarrhythmia.","E":"Rolandic epilepsy."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-20ddab69b820","duplicate_sources":[{"record_id":"3f139108e62dbcab29ee","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_page":180,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"3f139108e62dbcab29ee","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_year":2025,"source_page":180,"source_qid":null,"domain_hint":"Neurology","stem":"An eight-year-old boy is brought to your practice\nby his mother for what she calls funny turns in\nthe past several weeks. According to the\nmother, the boy have episodes of sudden stares\nalong with fidgeting of the right hand fingers and\nright arm, lip smacking and chewing movements\nwhile his head twitches to the right side. He has\n3 to 4 episodes every day with each lasting 60-\n90 seconds. There is always spontaneous\nresolution after which the child is confused for 1\nto 2 minutes before he becomes completely\nhimself and back to whatever he was doing\nbefore. Which one of the following is the most\nlikely diagnosis?","options":{"A":"Temporal lobe epilepsy.","B":"Juvenile myoclonic epilepsy.","C":"Absence seizure.","D":"Hypsarrhythmia.","E":"Rolandic epilepsy."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"20ddab69b8206a77629f2a399caf2aa47367fb78","duplicate_group_id":"exact-20ddab69b820","duplicate_sources":[{"record_id":"3f139108e62dbcab29ee","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (2).pdf","source_page":180,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
