INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1ba01ae842bf5f421150','AMEDEX 2025 NEUROLOGY (3).pdf','10','Neurology','A 35-year-old woman presents with a complaint
of headaches. She describes that she has been
having these headaches for the past 8 months.
The headaches occur more often in the evening
hours, and she took Panadol, ibuprofen, and
sometimes codeine for pain relief. Recently, the
varying intensity headache comes early in the
morning and wakes her up. The ache is felt in
the frontal area bilaterally, and it seems that her
regular painkillers are not that effective, with
only partial relief lasting not more than 2 to
3 hours. She denies nausea and vomiting, light
and noise sensitivity, or visual problems. She is
otherwise in good shape, smokes 5-10
cigarettes a day, and drinks within a healthy
limit. Physical examination is inconclusive.
Which one of the following conditions is most
likely to have led to this presentation?','{"A":"Pseudotumor cerebri.","B":"Migraine.","C":"Tension headaches.","D":"Drug rebound headache.","E":"Cerebral tumour. ©"}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-fbf6066e058c","duplicate_sources":[{"record_id":"1ba01ae842bf5f421150","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","source_page":10,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"1ba01ae842bf5f421150","source_file":"AMEDEX 2025 NEUROLOGY (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","source_year":2025,"source_page":10,"source_qid":null,"domain_hint":"Neurology","stem":"A 35-year-old woman presents with a complaint\nof headaches. She describes that she has been\nhaving these headaches for the past 8 months.\nThe headaches occur more often in the evening\nhours, and she took Panadol, ibuprofen, and\nsometimes codeine for pain relief. Recently, the\nvarying intensity headache comes early in the\nmorning and wakes her up. The ache is felt in\nthe frontal area bilaterally, and it seems that her\nregular painkillers are not that effective, with\nonly partial relief lasting not more than 2 to\n3 hours. She denies nausea and vomiting, light\nand noise sensitivity, or visual problems. She is\notherwise in good shape, smokes 5-10\ncigarettes a day, and drinks within a healthy\nlimit. Physical examination is inconclusive.\nWhich one of the following conditions is most\nlikely to have led to this presentation?","options":{"A":"Pseudotumor cerebri.","B":"Migraine.","C":"Tension headaches.","D":"Drug