INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('91b440bdd11253e474b7','AMEDEX 2025 NEUROLOGY (3).pdf','17','Neurology','A 70-year-old man is being evaluated for
further management after he recovered from
an episode of transient ischemic attack (TIA).
On examination, his blood pressure is
180/110 mmHg and a bruit is heard over the
right carotid artery. A Duplex Doppler
ultrasonography of carotid arteries is
performed, which is significant for 50% and
60% stenosis of the right and left carotid
arteries, respectively. Which one of the
following options is the most appropriate
management for prevention of further
thromboembolic phenomena?','{"A":"A Hypertension control.","B":"BRB Aspirin.","C":"Cc Warfarin.","D":"Db Carotid endarterectomy.","E":"FE Clopidogrel."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","supporting_pages":[17],"source_qid":null,"duplicate_group_id":"exact-591140211b20","duplicate_sources":[{"record_id":"91b440bdd11253e474b7","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","source_page":17,"source_qid":null},{"record_id":"c68a11c9785fa2c6a9db","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":723,"source_qid":"1075"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"91b440bdd11253e474b7","source_file":"AMEDEX 2025 NEUROLOGY (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","source_year":2025,"source_page":17,"supporting_pages":[17],"source_qid":null,"domain_hint":"Neurology","stem":"A 70-year-old man is being evaluated for\nfurther management after he recovered from\nan episode of transient ischemic attack (TIA).\nOn examination, his blood pressure is\n180/110 mmHg and a bruit is heard over the\nright carotid artery. A Duplex Doppler\nultrasonography of carotid arteries is\nperformed, which is significant for 50% and\n60% stenosis of the right and left carotid\narteries, respectively. Which one of the\nfollowing options is the most appropriate\nmanagement for prevention of further\nthromboembolic phenomena?","options":{"A":"A Hypertension control.","B":"BRB Aspirin.","C":"Cc Warfarin.","D":"Db Carotid endarterectomy.","E":"FE Clopidogrel."},"source_answer":null,"source_explan