INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('6f9bcaf81523b74d6178','AMEDEX 2025 NEUROLOGY (3).pdf','34','Neurology','A 16-year-old girl comes to your GP clinic
requesting genetic testing for Huntington
disease. She is very distressed because her
father was diagnoses with the disease two
months ago. She surfed the internet about the
disease and has known that the disease is
inheritable and she may develop it later in life.
she says that this is her decision and her
parents do not Know anything about her
request. She does not want to inform them.
Which one of the following is the most
appropriate action in this situation?','{"A":"Arrange the genetic test for her.","B":"Tell her that she needs to comeback\nfor the test when she is 18 years old.","C":"Arrange for the whole family to have\ngenetic counselling.","D":"Tell her parents’ consent is required\nfor genetic testing.","E":"seeking a court order before\nproceeding to the test."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-3ed5932de6a2","duplicate_sources":[{"record_id":"6f9bcaf81523b74d6178","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","source_page":34,"source_qid":null},{"record_id":"92537fd49730f8421566","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":756,"source_qid":"1273"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"6f9bcaf81523b74d6178","source_file":"AMEDEX 2025 NEUROLOGY (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","source_year":2025,"source_page":34,"source_qid":null,"domain_hint":"Neurology","stem":"A 16-year-old girl comes to your GP clinic\nrequesting genetic testing for Huntington\ndisease. She is very distressed because her\nfather was diagnoses with the disease two\nmonths ago. She surfed the internet about the\ndisease and has known that the disease is\ninheritable and she may develop it later in life.\nshe says that this is her decision and her\nparents do not Know anything about her\nrequest. She does not want to inform them.\nWhich one of the following is the most\nappropriate action in this situation?","options":{"A":"Arra