INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b3b70cbaef5f0e0b86c6','AMEDEX 2025 NEUROLOGY (3).pdf','37','Neurology','This girl should be told that she cannot have the
genetic test until she is 18 years old.
(Option A) Arrangement for the genetic test for her
is incorrect and she can have the test at the age of
18 years or older.
(Option C) Arrangement for offspring of this family
is only performed upon their request provided that
they fulfill the criteria of predictive genetic testing
for HD.
(Option D) Parents cannot consent to or request
for HD predictive genetic testing on the minors’
behalves. Once the minor are 18 years no parental
consent for testing is required.
(Option E) Acompetent adult can request for the
test. A court order is required where guidelines are
unclear for decision making.
Reference(s) «Can children and young people c
onsent to be tested for adult onset
