INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d5fda1281e2d52e6d1f3','AMEDEX 2025 NEUROLOGY (3).pdf','39','Neurology','A 65-year-old man presents to a GP clinic for
what he believe Is vertigo. At work, when he
stood up from a sitting position, he felt dizzy and
nauseated. He feels ok now and does not have
the symptoms anymore. He is a known case of
diabetes and ischemic heart disease, and is
currently on valsartan, metoprolol, atorvastatin,
metformin and glimepiride. On physical
examination, his vital signs are within normal
limits and the rest of the examination including a
full neurological exam is unremarkable.
Laboratory tests are only significant for a
random serum glucose level of 11 mmol/L and
HbA1C level of 7%. An ECG is obtained which
is normal. Which one of the following is the
