INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('56e96ffba78e096f3961','AMEDEX 2025 NEUROLOGY (3).pdf','123','Neurology','A 12-year-old boy is brought to your office after accidentally cutting his left wrist with a pocketknife. On examination, there is a deep 2-cm laceration at the base of the thenar eminence. To test the motor injury to the median nerve you would have the patient:',NULL,'B','Option B Is correct

The scenario describes a cut in the thenar area of
this child.

There are three muscles in the thenar

eminence:

1. abductor pollicis brevis
2. flexor pollicis brevis
3. Opponens pollicis.
Median nerve injury at wrist level results in the
dysfunction of these three muscles (as well as the
lumbrical muscles of the digits 2 and 3).

The first two muscles are conjoined with fibers
from their counterparts originating from forearm,
namely abductor pollicis longus and flexor pollicis
longus. While median nerve injury at wrist level
causes the dysfunction of thenar region muscles,
thumb abduction and flexion remain preserved due
to compensatory action of abductor pollicis longus
and flexor pollicis longus muscles. However, thumb
opposition becomes severely impaired due to
denervation of the opponens pollicis muscle.
Isolated impairment of thumb opposition is the
most likely finding in median nerve injuries at wrist

level.

(Option A) Extension of the thumb and fingers is

an action of radial nerve and is not affected by

median nerve injuries.

_ _- — i.

(Option A) Extension of the thumb and fingers is

an action of radial nerve and is not affected by

median nerve injuries.

(Option C) Wrist flexion is mainly the action of
flexor carpi radialis and flexor carpi ulnaris
muscles, innervated by the median and ulnar
nerves, respectively, in the forearm. Median and
ulnar nerve injuries in the wrist will not affect wrist
flexion; therefore, this movement will be unaffected

in this patient.

(Option D) While median nerve injury at wrist can
impair the function of abductor pollicis brevis in the
thenar eminence, thumb abduction is preserved to
a great extend, because the fibers of abductor
pollicis longus are innervated in the forearm by the
anterior interosseous nerve (a branch of median
nerve) and unaffected by injury to the median
nerve at wrist level. Therefore, this action is
preserved. Abduction of other fingers than the
thumb are provided by dorsal interosseous
muscles and abductor digiti minimi, all supplied by
the ulnar nerve; hence unaffected in this patient.

(Option E) Thumb adduction is mainly provided by
the muscle adductor pollicis that is innervated by
the deep branch of the ulnar nerve. Median nerve
injury at wrist level is unlikely to significantly affect
this movement. Adduction of the other fingers other
than the thumb are the action of palmar

interosseous muscles all innervated by ulnar nerve

and is not expected to be impaired in this patie','{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","supporting_pages":[123,124,125,126],"source_qid":null,"duplicate_group_id":null,"duplicate_sources":[],"parser_version":"manual-review-batch010-2026-09-24","parser_mode":"human_visual_review_batch010","text_method":"manual_visual_plus_context","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','low','{"record_id":"56e96ffba78e096f3961","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","source_year":2025,"source_page":123,"supporting_pages":[123,124,125,126],"source_qid":null,"domain_hint":"Neurology","stem":"A 12-year-old boy is brought to your office after accidentally cutting his left wrist with a pocketknife. On examination, there is a deep 2-cm laceration at the base of the thenar eminence. To test the motor injury to the median nerve you would have the patient:","options":{},"options_mode":"text","source_answer":"B","source_explanation":"Option B Is correct\n\nThe scenario describes a cut in the thenar area of\nthis child.\n\nThere are three muscles in the thenar\n\neminence:\n\n1. abductor pollicis brevis\n2. flexor pollicis brevis\n3. Opponens pollicis.\nMedian nerve injury at wrist level results in the\ndysfunction of these three muscles (as well as the\nlumbrical muscles of the digits 2 and 3).\n\nThe first two muscles are conjoined with fibers\nfrom their counterparts originating from forearm,\nnamely abductor pollicis longus and flexor pollicis\nlongus. While median nerve injury at wrist level\ncauses the dysfunction of thenar region muscles,\nthumb abduction and flexion remain preserved due\nto compensatory action of abductor pollicis longus\nand flexor pollicis longus muscles. However, thumb\nopposition becomes severely impaired due to\ndenervation of the opponens pollicis muscle.\nIsolated impairment of thumb opposition is the\nmost likely finding in median nerve injuries at wrist\n\nlevel.\n\n(Option A) Extension of the thumb and fingers is\n\nan action of radial nerve and is not affected by\n\nmedian nerve injuries.\n\n_ _- — i.\n\n(Option A) Extension of the thumb and fingers is\n\nan action of radial nerve and is not affected by\n\nmedian nerve injuries.\n\n(Option C) Wrist flexion is mainly the action of\nflexor carpi radialis and flexor carpi ulnaris\nmuscles, innervated by the median and ulnar\nnerves, respectively, in the forearm. Median and\nulnar nerve injuries in the wrist will not affect wrist\nflexion; therefore, this movement will be unaffected\n\nin this patient.\n\n(Option D) While median nerve injury at wrist can\nimpair the function of abductor pollicis brevis in the\nthenar eminence, thumb abduction is preserved to\na great extend, because the fibers of abductor\npollicis longus are innervated in the forearm by the\nanterior interosseous nerve (a branch of median\nnerve) and unaffected by injury to the median\nnerve at wrist level. Therefore, this action is\npreserved. Abduction of other fingers than the\nthumb are provided by dorsal interosseous\nmuscles and abductor digiti minimi, all supplied by\nthe ulnar nerve; hence unaffected in this patient.\n\n(Option E) Thumb adduction is mainly provided by\nthe muscle adductor pollicis that is innervated by\nthe deep branch of the ulnar nerve. Median nerve\ninjury at wrist level is unlikely to significantly affect\nthis movement. Adduction of the other fingers other\nthan the thumb are the action of palmar\n\ninterosseous muscles all innervated by ulnar nerve\n\nand is not expected to be impaired in this patie","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"human_visual_review_batch010","text_method":"manual_visual_plus_context","parser_version":"manual-review-batch010-2026-09-24","visual_asset":null,"visual_source_page":null,"manual_review_batch":"010","manual_review_source_key":"","stem_hash":"cfa91d945ffbbe81baf92bd3a56976d27864939883408cb75e99b29f5cf30647"}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
