INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1b9adfb24e97f45e7c5a','AMEDEX 2025 NEUROLOGY (3).pdf','128','Neurology','A 5-year-old boy is brought to your practice by
his parents for assessment. According to the
parents, he has several episodes of blank stare
while watching TV every day, which are
accompanied by bizarre movements of the head
and right hand. The trunk and head turn before
Starts fidgeting the fingers of his right hand and
smacking his lips. He seems lost during an
attack. There are up to 10 episodes almost
every day, each lasting about one minute before
spontaneous resolution occurs. He seems
confused and drowsy for 1 to 2 minutes after
each attack. Which one of the following is the
most appropriate treatment option for him?','{"A":"Phenytoin.","B":"Sodium valproate.\nov CG Ethosuximide.","C":"Carbamazepine.","D":"— Phenobarbital.","E":"O"}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-109a4ba243bd","duplicate_sources":[{"record_id":"1b9adfb24e97f45e7c5a","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","source_page":128,"source_qid":null},{"record_id":"f05f5b793870ff83641c","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","source_page":127,"source_qid":null},{"record_id":"84277b7d6962a779e1a8","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":774,"source_qid":"1313"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"1b9adfb24e97f45e7c5a","source_file":"AMEDEX 2025 NEUROLOGY (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","source_year":2025,"source_page":128,"source_qid":null,"domain_hint":"Neurology","stem":"A 5-year-old boy is brought to your practice by\nhis parents for assessment. According to the\nparents, he has several episodes of blank stare\nwhile watching TV every day, which are\naccompanied by bizarre movements of the head\nand right hand. The trunk and head turn before\nStarts fidgeting the fingers of his right hand and\nsmacking his lips. He seems lost during an\nattack. There are up to 10 episodes almost\nevery day, each lasting about one minute before\nspontaneous resolution occurs. He seems\nconfused and drowsy for 1 to 2 minutes after\neach attack. Which one of the following is the\nmost appropriate treatment option for him?","options":{"A":"Phenytoin.","B":"Sodium valproate.\nov CG Ethosuximide.","C":"Carbamazepine.","D":"— Phenobarbital.","E":"O"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["treatment"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"109a4ba243bd0afc26f1e0fd35bdbfd53afa860d","duplicate_group_id":"exact-109a4ba243bd","duplicate_sources":[{"record_id":"1b9adfb24e97f45e7c5a","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","source_page":128,"source_qid":null},{"record_id":"f05f5b793870ff83641c","record_type":"text_mcq","source_file":"AMEDEX 2025 NEUROLOGY (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 NEUROLOGY (3).pdf","source_page":127,"source_qid":null},{"record_id":"84277b7d6962a779e1a8","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":774,"source_qid":"1313"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_stat